import math


def evaluate(expr: str) -> int:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            j = i
            while j < n and "0" <= expr[j] <= "9":
                j += 1
            tokens.append(expr[i:j])
            i = j
        elif ch in "+-*/%^!()":
            tokens.append(ch)
            i += 1
        else:
            raise ValueError(f"Invalid character: {ch!r}")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0
    num_tokens = len(tokens)

    def peek() -> str | None:
        return tokens[pos] if pos < num_tokens else None

    def consume() -> str:
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_add() -> int:
        val = parse_mul()
        while True:
            tok = peek()
            if tok == "+":
                consume()
                val += parse_mul()
            elif tok == "-":
                consume()
                val -= parse_mul()
            else:
                break
        return val

    def parse_mul() -> int:
        val = parse_unary()
        while True:
            tok = peek()
            if tok == "*":
                consume()
                val *= parse_unary()
            elif tok == "/":
                consume()
                rhs = parse_unary()
                if rhs == 0:
                    raise ValueError("Division by zero")
                q = abs(val) // abs(rhs)
                if (val < 0) ^ (rhs < 0):
                    q = -q
                val = q
            elif tok == "%":
                consume()
                rhs = parse_unary()
                if rhs == 0:
                    raise ValueError("Remainder by zero")
                q = abs(val) // abs(rhs)
                if (val < 0) ^ (rhs < 0):
                    q = -q
                val = val - q * rhs
            elif tok == "(":
                val *= parse_unary()
            else:
                break
        return val

    def parse_unary() -> int:
        neg = False
        while peek() == "-":
            consume()
            neg = not neg
        val = parse_pow()
        return -val if neg else val

    def parse_pow() -> int:
        base = parse_postfix()
        if peek() == "^":
            consume()
            exp = parse_unary()
            if exp < 0:
                raise ValueError("Negative exponent")
            return base ** exp
        return base

    def parse_postfix() -> int:
        val = parse_primary()
        while peek() == "!":
            consume()
            if val < 0:
                raise ValueError("Factorial of a negative number")
            val = math.factorial(val)
        return val

    def parse_primary() -> int:
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok == "(":
            consume()
            val = parse_add()
            if peek() != ")":
                raise ValueError("Expected ')'")
            consume()
            return val
        if "0" <= tok[0] <= "9":
            consume()
            return int(tok)
        raise ValueError(f"Unexpected token: {tok!r}")

    result = parse_add()
    if pos != num_tokens:
        raise ValueError(f"Unexpected token: {tokens[pos]!r}")
    return result
